-- 办公平台基础表
CREATE TABLE IF NOT EXISTS office_platform_app (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, platform VARCHAR(32) NOT NULL, app_id VARCHAR(128) NOT NULL, secret_reference VARCHAR(255) NOT NULL, redirect_uri VARCHAR(512), signing_secret_reference VARCHAR(255), capabilities TEXT, enabled SMALLINT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 0, deleted SMALLINT NOT NULL DEFAULT 0, create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS office_identity_binding (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, user_id BIGINT NOT NULL, platform VARCHAR(32) NOT NULL, external_user_id VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL, enabled SMALLINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 0, deleted SMALLINT NOT NULL DEFAULT 0, create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS office_organization_mapping (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, platform VARCHAR(32) NOT NULL, external_org_id VARCHAR(255) NOT NULL, external_user_id VARCHAR(255), apex_dept_id VARCHAR(64), apex_user_id VARCHAR(64), version INT NOT NULL DEFAULT 0, deleted SMALLINT NOT NULL DEFAULT 0, create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS office_sync_task (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, platform VARCHAR(32) NOT NULL, cursor_value VARCHAR(512), state VARCHAR(32) NOT NULL, failure_message VARCHAR(1000), version INT NOT NULL DEFAULT 0, deleted SMALLINT NOT NULL DEFAULT 0, create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE UNIQUE INDEX IF NOT EXISTS uk_office_app_tenant_platform ON office_platform_app (tenant_id, platform);
CREATE UNIQUE INDEX IF NOT EXISTS uk_office_binding_external ON office_identity_binding (tenant_id, platform, external_user_id);
CREATE UNIQUE INDEX IF NOT EXISTS uk_office_binding_user ON office_identity_binding (tenant_id, platform, user_id);
CREATE UNIQUE INDEX IF NOT EXISTS uk_office_org ON office_organization_mapping (tenant_id, platform, external_org_id);
CREATE UNIQUE INDEX IF NOT EXISTS uk_office_sync ON office_sync_task (tenant_id, platform);
